public List<List<String>> solveNQueens(int n) {
    List<List<String>> results = new ArrayList<>();
    int[] queens = new int[n];                 // queens[r] = column of the queen in row r
    boolean[] cols = new boolean[n];
    boolean[] diag = new boolean[2 * n - 1];       // index by row + col
    boolean[] antiDiag = new boolean[2 * n - 1];   // index by row - col + (n - 1)
    backtrack(0, n, queens, cols, diag, antiDiag, results);
    return results;
}

private void backtrack(int row, int n, int[] queens, boolean[] cols,
                       boolean[] diag, boolean[] antiDiag, List<List<String>> results) {
    if (row == n) {
        results.add(build(queens, n));         // all queens placed → record the board
        return;
    }
    for (int col = 0; col < n; col++) {
        int d = row + col;
        int ad = row - col + n - 1;
        if (cols[col] || diag[d] || antiDiag[ad]) continue;   // square attacked → prune
        queens[row] = col;
        cols[col] = diag[d] = antiDiag[ad] = true;            // choose
        backtrack(row + 1, n, queens, cols, diag, antiDiag, results); // explore next row
        cols[col] = diag[d] = antiDiag[ad] = false;           // un-choose
    }
}

private List<String> build(int[] queens, int n) {
    List<String> board = new ArrayList<>();
    for (int r = 0; r < n; r++) {
        char[] rowChars = new char[n];
        Arrays.fill(rowChars, '.');
        rowChars[queens[r]] = 'Q';
        board.add(new String(rowChars));
    }
    return board;
}

